UPDATE public.profiles SET
  username = 'lc-the-architect',
  full_name = 'The Architect',
  profession = 'Architect',
  location = 'Casablanca',
  bio = 'The Architect studio est un cabinet d’architecture contemporain qui allie élégance, innovation et durabilité. Animés par la passion de concevoir des espaces uniques, nous intervenons dans la création de villas, immeubles, bureaux et projets publics,…',
  about_text = 'The Architect studio est un cabinet d’architecture contemporain qui allie élégance, innovation et durabilité. Animés par la passion de concevoir des espaces uniques, nous intervenons dans la création de villas, immeubles, bureaux et projets publics, en offrant à chaque client une expérience sur mesure, où design, fonctionnalité et confort se rencontrent harmonieusement. Chez The Architect, chaque projet est une œuvre pensée dans le détail — du concept initial à la réalisation — avec une attention particulière portée à la qualité, à l’intégration du contexte et à la durabilité des matériaux. Notre vision : façonner une architecture intemporelle, qui valorise les lieux et sublime la vie de ceux qui les habitent. The Architect — Créer, innover, inspirer.',
  phone = '+212661670149',
  email = 'contact@sijelmassi-architecte.com',
  website_url = 'https://sijelmassi-architecte.com/index-en',
  ice = '003045764000002',
  avatar_url = 'https://tachrone-profile-logos-pro.s3.eu-west-3.amazonaws.com/file-4613.png',
  cover_photo_url = 'https://sijelmassi-architecte.com/img/hero/marina-480.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1),
  updated_at = NOW()
WHERE id = 'd76b3878-d325-5ea7-91e8-9dcfd74f05b7'::uuid;
