UPDATE public.profiles SET
  username = 'lc-adaassociates',
  full_name = 'ADA & associates',
  profession = 'Architect',
  location = 'Casablanca',
  bio = 'Nous accompagnons nos clients dans la conception et le développement de projets architecturaux, depuis les premières études jusqu’à la préparation technique, l’assistance au projet et la réception définitive. Notre approche vise à créer des espaces f…',
  about_text = 'Nous accompagnons nos clients dans la conception et le développement de projets architecturaux, depuis les premières études jusqu’à la préparation technique, l’assistance au projet et la réception définitive. Notre approche vise à créer des espaces fonctionnels, harmonieux et en cohérence avec l’identité et les objectifs de chaque projet. Domaines de compétence: Conception et design architectural • Études de faisabilité et analyse de site. • Développement conceptuel et élaboration de projets. • Organisation spatiale et optimisation fonctionnelle. • Design intérieur et esthétique de l''espace. Appui technique et suivi de projet • Préparation et coordination des plans et documents techniques • Collaboration avec les bureaux d’études et intervenants du projet. • Vérification de la cohérence technique et réglementaire. Conseil et accompagnement client • Appui à la prise de décision aux différentes étapes du projet. • Recommandations sur les choix techniques et architecturaux • Assistance en phase de pré-construction et préparation à l’exécution • Suivit de chantier et coodination avec le maître d''ouvrage.',
  phone = '0662325819',
  email = 'lc-adaassociates@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003582238000020',
  avatar_url = 'https://lechantier.ma/uploads/media/1e67a9951d67.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/1e67a9951d67.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1),
  updated_at = NOW()
WHERE id = '9dd41569-694b-5383-ab54-adc2acb55322'::uuid;
