UPDATE public.profiles SET
  username = 'lc-fardiibtissamarchitecte',
  full_name = 'FARDI IBTISSAM ARCHITECTE',
  profession = 'Architecte',
  location = 'Casablanca',
  bio = 'Présentation de l’entreprise FARDI IBTISSAM ARCHITECTE SARL est une entreprise marocaine basée à Médiouna – Casablanca, spécialisée dans les domaines de l’architecture, du design intérieur et de l’aménagement paysager. Forte de deux années d’expérien…',
  about_text = 'Présentation de l’entreprise FARDI IBTISSAM ARCHITECTE SARL est une entreprise marocaine basée à Médiouna – Casablanca, spécialisée dans les domaines de l’architecture, du design intérieur et de l’aménagement paysager. Forte de deux années d’expérience, notre structure s''engage à proposer des solutions innovantes, esthétiques et fonctionnelles, adaptées aux besoins de nos clients – particuliers, professionnels ou collectivités. Nos domaines d’intervention : 🏛️ Architecture : Conception de bâtiments résidentiels, commerciaux ou institutionnels, en harmonie avec leur environnement et répondant aux normes techniques, urbaines et esthétiques. 🏠 Design d’intérieur : Création d’espaces intérieurs optimisés, confortables et stylisés, alliant fonctionnalité et raffinement selon les goûts et usages du client. 🌿 Architecture paysagère : Aménagement d’espaces extérieurs – jardins, patios, parcs – mettant en valeur la nature et favorisant bien-être et convivialité. Notre philosophie : Chez FARDI IBTISSAM ARCHITECTE, chaque projet est unique. Nous adoptons une approche humaine et personnalisée, fondée sur l’écoute, la créativité et la rigueur technique. Notre jeune équipe, passionnée et formée aux dernières tendances et outils de conception, s’engage à transformer les idées en espaces de vie harmonieux et durables.',
  phone = '+212682347210',
  email = 'lc-fardiibtissamarchitecte@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003721661000072',
  avatar_url = 'https://lechantier.ma/uploads/media/8260a0ca0da9.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/8260a0ca0da9.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1),
  updated_at = NOW()
WHERE id = '53c127b5-a607-53eb-a0d7-f0eac6afa908'::uuid;
UPDATE public.profiles SET
  username = 'lc-1007architects',
  full_name = '1007 ARCHITECTS',
  profession = 'Architect',
  location = 'Rabat',
  bio = '1007 ARCHITECTS est une agence d’architecture spécialisée en conception architecturale, architecture d’intérieur et BIM. Elle accompagne ses clients à chaque étape du projet, de l’étude à la réalisation, en proposant des solutions créatives, fonction…',
  about_text = '1007 ARCHITECTS est une agence d’architecture spécialisée en conception architecturale, architecture d’intérieur et BIM. Elle accompagne ses clients à chaque étape du projet, de l’étude à la réalisation, en proposant des solutions créatives, fonctionnelles et durables. Son expertise en architecture permet de concevoir des bâtiments esthétiques, bien intégrés dans leur environnement et adaptés aux usages. En architecture d’intérieur, l’agence imagine des espaces harmonieux, optimisés et personnalisés, en jouant avec la lumière, les volumes et les matériaux pour créer des ambiances uniques. Grâce à la maîtrise du BIM (Building Information Modeling), 1007 ARCHITECTS assure une meilleure coordination entre les intervenants, une gestion précise des données et une optimisation des délais et des coûts, tout au long du projet. Portée par une vision contemporaine et une approche collaborative, l’agence place l’innovation, le confort et la qualité de vie au cœur de chaque mission. Que ce soit pour des logements, des équipements, des espaces professionnels ou des projets d’aménagement intérieur, 1007 ARCHITECTS conçoit des espaces modernes, durables et adaptés aux besoins de demain.',
  phone = '0779000037',
  email = 'lc-1007architects@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003460779000037',
  avatar_url = 'https://lechantier.ma/uploads/media/5a0407038184.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/5a0407038184.webp',
  profile_type = 'enterprise',
