UPDATE public.profiles SET
  username = 'lc-aminebencheqrounarchitecte',
  full_name = 'Amine Bencheqroun Architecte',
  profession = 'entreprise',
  location = 'Mi Vida',
  bio = 'Fondée sur l’héritage de l’agence Bencheqroun & Benjelloun, créée en 1985, notre structure actuelle capitalise sur plus de 40 d’expérience architecturale au Maroc. Portée par une nouvelle génération d’architectes, elle allie exigence conceptuelle, ma…',
  about_text = 'Fondée sur l’héritage de l’agence Bencheqroun & Benjelloun, créée en 1985, notre structure actuelle capitalise sur plus de 40 d’expérience architecturale au Maroc. Portée par une nouvelle génération d’architectes, elle allie exigence conceptuelle, maîtrise technique et ouverture internationale. Notre agence s’est affirmée au fil des années comme un acteur de référence dans la conception d’immeubles, de villas, d’écoles, de sièges d’entreprise, de showrooms et d’espaces professionnels, en accompagnant des groupes de premier plan tels que : Inwi, Attijariwafa Bank, CIH Bank, CAC, SMEIA, Mitsubishi Motors, T2S, M Automotive, ainsi que diverses institutions et sociétés privées. Nous intervenons à toutes les échelles du projet, de la conception architecturale à la mise en œuvre, avec une attention particulière portée à l’image de marque, au confort des usagers et à la qualité des finitions. Cette expertise s’exprime aussi bien dans des environnements tertiaires que dans des espaces techniques, industriels ou commerciaux. Notre travail, reconnu par plusieurs distinctions et publications, s’est notamment illustré à travers des projets comme le Grand Théâtre de Fès, en cours de réalisation. Nous mettons aujourd’hui cette expérience au service de maîtres d’ouvrage nationaux et internationaux, en proposant des prestations complètes ou externalisées, dans le respect des standards graphiques et techniques européens.',
  phone = '+212662039492',
  email = 'lc-aminebencheqrounarchitecte@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003509624000034',
  avatar_url = 'https://lechantier.ma/uploads/media/4bc5d1506f95.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/4bc5d1506f95.webp',
  profile_type = 'enterprise',
