UPDATE public.profiles SET
  username = 'lc-archiplanarchitectesassocies',
  full_name = 'Archiplan Architectes Associés',
  profession = 'Architecte',
  location = 'Meknès',
  bio = 'Archiplan, agence d''architecture à Meknès au Maroc, conçoit des projets durables adaptés au contexte marocain. De l''idée au chantier, nous vous accompagnons dans tout le Maroc. Expertise d''architectes à Meknès, rayonnement national Chez Archiplan, no…',
  about_text = 'Archiplan, agence d''architecture à Meknès au Maroc, conçoit des projets durables adaptés au contexte marocain. De l''idée au chantier, nous vous accompagnons dans tout le Maroc. Expertise d''architectes à Meknès, rayonnement national Chez Archiplan, notre ambition est de mettre l’architecture au service de l’humain, de l’environnement et du patrimoine. Basés à Meknès, nous accompagnons particuliers, promoteurs et institutions dans la conception, la rénovation et la construction de projets variés : villas modernes, bâtiments publics, projets éducatifs, logements collectifs ou encore espaces culturels. Notre approche est à la fois contextuelle, fonctionnelle et créative. Grâce à plus de 60 ans d’expérience cumulée, nos architectes diplômés de France intègrent les meilleures pratiques du design bioclimatique, des technologies intelligentes (IA, BIM) et de la durabilité dans chaque projet. Des solutions sur mesure pour chaque projet architectural Archiplan vous accompagne de l’esquisse initiale à la livraison du chantier, avec une attention constante portée aux besoins des usagers, aux contraintes du site et à la qualité architecturale. Nos projets sont menés avec rigueur, innovation et transparence. Conception architecturale assistée par IA Rénovation et réhabilitation durable Architecture bioclimatique et intégration paysagère Gestion de projet et suivi de chantier intelligent Rendus 3D photoréalistes',
  phone = '0535521028',
  email = 'lc-archiplanarchitectesassocies@lechantier.sifarah.local',
  website_url = NULL,
  ice = '001654099000067',
  avatar_url = 'https://lechantier.ma/uploads/media/92dd386134ef.webp',
