UPDATE public.profiles SET
  username = 'lc-forum-diffusion',
  full_name = 'FORUM DIFFUSION',
  profession = 'Furniture',
  location = 'Rabat',
  bio = 'FORUM DIFFUSION, basée à Rabat, est spécialisée dans l’aménagement et l’équipement d’espaces de travail professionnels. Depuis sa création, l’entreprise accompagne les organisations dans la conception de bureaux modernes, ergonomiques et adaptés aux…',
  about_text = 'FORUM DIFFUSION, basée à Rabat, est spécialisée dans l’aménagement et l’équipement d’espaces de travail professionnels. Depuis sa création, l’entreprise accompagne les organisations dans la conception de bureaux modernes, ergonomiques et adaptés aux besoins de leurs équipes. Nous proposons une large gamme de mobilier de bureau : bureaux individuels ou bench partagés, postes de direction, sièges ergonomiques, armoires, rangements modulables, cloisons, ainsi que des solutions pour open spaces et flex office. Chaque projet est pensé pour allier fonctionnalité, confort et esthétique, afin de créer des environnements favorisant productivité et bien-être. En complément, FORUM DIFFUSION fournit le matériel de bureau indispensable : photocopieurs, imprimantes, destructeurs, vidéoprojecteurs, coffres-forts et tableaux magnétiques. Cette offre intégrée permet d’apporter des solutions complètes et personnalisées, couvrant à la fois mobilier et équipement technique. Nos clients – TPE, PME, grandes entreprises et administrations – bénéficient d’un accompagnement global, de l’analyse des besoins jusqu’à l’installation. Notre engagement repose sur trois valeurs : qualité, respect des délais et solutions sur mesure. Forts de notre expertise, nous faisons de chaque espace un lieu fonctionnel, performant et inspirant.',
  phone = '+212661296837',
  email = 'info@forumdiffusion.ma',
  website_url = 'https://www.forumdiffusion.ma',
  ice = '001550178000015',
  avatar_url = 'https://lechantier.ma/uploads/media/4abb815930ce.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/4abb815930ce.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '4.2.5' LIMIT 1),
  updated_at = NOW()
WHERE id = '38c5bd4b-3446-5545-a89b-179425728b7f'::uuid;
