UPDATE public.profiles SET
  username = 'lc-nexusenergy',
  full_name = 'Nexus Energy',
  profession = 'Electrical equipment',
  location = 'Casablanca',
  bio = 'Fondée en 2020, Nexus Energy est une société marocaine spécialisée dans le négoce de matériels électriques, avec une ambition claire : devenir un acteur incontournable du secteur électrique en Afrique. Forte de son expertise technique et de son vaste…',
  about_text = 'Fondée en 2020, Nexus Energy est une société marocaine spécialisée dans le négoce de matériels électriques, avec une ambition claire : devenir un acteur incontournable du secteur électrique en Afrique. Forte de son expertise technique et de son vaste réseau de partenaires spécialisés, Nexus Energy offre une gamme complète de produits et services pour le tertiaire, l''infrastructure, l''industrie et les télécommunications. Avec des solutions couvrant les câbles, l''appareillage, l''éclairage, la sécurité, l''efficacité énergétique, l''automatisation et la cybersécurité, Nexus Energy répond aux besoins variés de ses clients avec flexibilité et innovation. Grâce à des partenariats exclusifs avec des leaders mondiaux comme TE Connectivity, Sermes, ABB, SDMO et Ormazabal, la société garantit des solutions de haute qualité pour les projets les plus exigeants. Reconnu pour sa fiabilité et son savoir-faire, Nexus Energy est le partenaire privilégié de grandes entreprises comme l''ONEE, Lydec et l''OCP, illustrant sa capacité à répondre aux défis énergétiques complexes du continent.',
  phone = '+212656567134',
  email = 'lc-nexusenergy@lechantier.sifarah.local',
  website_url = NULL,
  ice = '002980121000076',
  avatar_url = 'https://lechantier.ma/uploads/media/c978fb247817.webp',
