UPDATE public.profiles SET
  username = 'lc-ytsarchitecte',
  full_name = 'YTS ARCHITECTE',
  profession = 'Architect',
  location = 'Casablanca',
  bio = 'Notre cabinet s’attache à produire une architecture juste, lisible et ancrée dans son territoire. Nous abordons chaque projet avec la conviction que la forme n’a de sens que si elle clarifie l’usage, valorise le lieu et améliore la vie de ceux qui l’…',
  about_text = 'Notre cabinet s’attache à produire une architecture juste, lisible et ancrée dans son territoire. Nous abordons chaque projet avec la conviction que la forme n’a de sens que si elle clarifie l’usage, valorise le lieu et améliore la vie de ceux qui l’habitent. Nous privilégions une approche rigoureuse : compréhension fine du contexte, dialogue constant avec les acteurs du projet, attention exigeante portée aux matériaux, aux lumières et aux gestes qui structurent l’espace. Notre travail ne cherche pas à impressionner, mais à être pertinent, durable et cohérent.',
  phone = '0660148157',
