UPDATE public.profiles SET
  username = 'lc-sadkianassarchitecte',
  full_name = 'SADKI ANASS ARCHITECTE',
  profession = 'Architect',
  location = 'Fès',
  bio = 'SADKI ANASS ARCHITECTE est un cabinet d’architecture marocain fondé par Anass Sadki, architecte diplômé et passionné par la création d’espaces modernes, harmonieux et durables. Le cabinet exerce dans les domaines de l’architecture, de l’architecture…',
  about_text = 'SADKI ANASS ARCHITECTE est un cabinet d’architecture marocain fondé par Anass Sadki, architecte diplômé et passionné par la création d’espaces modernes, harmonieux et durables. Le cabinet exerce dans les domaines de l’architecture, de l’architecture d’intérieur et de l’urbanisme, en accompagnant ses clients à chaque étape du projet : conception, démarches administratives, suivi de chantier et livraison finale. Installé a Fès, le cabinet intervient sur tout le territoire national pour des projets de logements individuels et collectifs, d’équipements publics, de bâtiments tertiaires et d’aménagements urbains. La mission du cabinet est claire : concevoir des espaces qui allient beauté, fonctionnalité et pérennité, tout en respectant les contraintes techniques, réglementaires et environnementales. Chaque projet est considéré comme une œuvre sur mesure, née d’un dialogue étroit entre le client, le lieu et l’architecte. L’agence place l’écoute, la créativité et la rigueur au cœur de sa démarche, afin de transformer les idées en réalisations concrètes, cohérentes et inspirantes.',
  phone = '0664302550',
  email = 'lc-sadkianassarchitecte@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003730426000097',
  avatar_url = 'https://lechantier.ma/uploads/media/bdae5cd734b0.webp',
