UPDATE public.profiles SET
  username = 'lc-ateliertraverse',
  full_name = 'ATELIER TRAVERSE',
  profession = 'Architect',
  location = 'Marrakech',
  bio = 'Atelier Traverse est un studio d’architecture fondé avec la volonté de concevoir des espaces justes, durables et sensibles à leur contexte. Notre approche repose sur une lecture attentive des lieux, des usages et des contraintes, afin de proposer des…',
  about_text = 'Atelier Traverse est un studio d’architecture fondé avec la volonté de concevoir des espaces justes, durables et sensibles à leur contexte. Notre approche repose sur une lecture attentive des lieux, des usages et des contraintes, afin de proposer des réponses claires, cohérentes et pérennes. Nous intervenons sur différentes échelles de projet, de la conception architecturale au développement de l’image du projet, avec une attention particulière portée à la qualité spatiale, à la lumière, à la matière et à la lisibilité de chaque intention. Atelier Traverse défend une architecture sobre, contemporaine et ancrée dans le réel, où chaque choix trouve sa logique dans l’équilibre entre fonction, sens et expression. Nous accompagnons nos clients avec exigence et précision, en cherchant à transformer chaque contrainte en opportunité de projet. À travers une démarche rigoureuse et sensible, l’agence s’attache à produire une architecture essentielle, élégante et durable.',
  phone = '0687916931',
  email = 'lc-ateliertraverse@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003772527000016',
  avatar_url = 'https://lechantier.ma/uploads/media/62c186e5dcc3.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/62c186e5dcc3.webp',
  profile_type = 'enterprise',
