UPDATE public.profiles SET
  username = 'lc-agencea',
  full_name = 'AGENCE A',
  profession = 'Architect',
  location = 'Casablanca',
  bio = 'L’Agence A est un atelier d’architecture basé à Casablanca, spécialisé dans la conception d’espaces modernes, fonctionnels et porteurs de sens. Fondée sur des valeurs de rigueur, de créativité et d’écoute, l’agence intervient dans des projets d’habit…',
  about_text = 'L’Agence A est un atelier d’architecture basé à Casablanca, spécialisé dans la conception d’espaces modernes, fonctionnels et porteurs de sens. Fondée sur des valeurs de rigueur, de créativité et d’écoute, l’agence intervient dans des projets d’habitat collectif, de bâtiments tertiaires, d’ouvrages industriels et d’aménagements urbains. Nous accompagnons nos clients, promoteurs, maîtres d’ouvrage publics ou privés, de l’esquisse à la livraison, en assurant une qualité architecturale constante et une parfaite maîtrise des contraintes techniques, réglementaires et budgétaires. Notre approche repose sur : - Une architecture sobre et élégante, adaptée au contexte et aux usages. - Une gestion fluide des projets, grâce à des outils BIM et un suivi rigoureux des études et des chantiers. - Une attention particulière portée à la durabilité, l’impact environnemental et l’intégration urbaine. Avec un regard contemporain et une équipe agile, l’Agence A conçoit des projets qui traduisent l’ambition de ses partenaires et la richesse de chaque site.',
  phone = '0622815864',
  email = 'lc-agencea@lechantier.sifarah.local',
  website_url = NULL,
  ice = '002033259000030',
  avatar_url = 'https://lechantier.ma/uploads/media/b0563f90008b.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/b0563f90008b.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1),
