UPDATE public.profiles SET
  username = 'lc-ingebattsarl',
  full_name = 'INGEBATT SARL',
  profession = 'Engineering firm',
  location = 'Casablanca',
  bio = 'Basé à Casablanca, INGEBATT est un bureau d’études techniques spécialisé en ingénierie structurelle. Depuis plus de 30 ans, nous accompagnons promoteurs, architectes et entreprises dans la conception et l’optimisation de leurs projets de construction…',
  about_text = 'Basé à Casablanca, INGEBATT est un bureau d’études techniques spécialisé en ingénierie structurelle. Depuis plus de 30 ans, nous accompagnons promoteurs, architectes et entreprises dans la conception et l’optimisation de leurs projets de construction à travers tout le Maroc. Notre expertise couvre les études de structures béton armé, métalliques et mixtes, pour des projets résidentiels, tertiaires, industriels ou hôteliers. Nous intervenons sur l’ensemble des phases d’un projet : avant-projet, dimensionnement, plans d’exécution, notes de calculs, suivi technique et assistance au chantier. Notre équipe est composée d’ingénieurs expérimentés et de projeteurs qualifiés, engagés à produire des livrables fiables, précis et conformes aux normes en vigueur. Nous privilégions la rigueur, la réactivité et le respect des délais, tout en restant à l’écoute de nos partenaires. Avec plusieurs centaines de projets réalisés, INGEBATT s’est imposé comme un acteur reconnu du secteur. Nous mettons un point d’honneur à proposer des solutions techniques optimisées, parfaitement adaptées aux exigences de chaque projet.',
  phone = '0666120685',
  email = 'lc-ingebattsarl@lechantier.sifarah.local',
  website_url = NULL,
  ice = '000084384000065',
  avatar_url = 'https://lechantier.ma/uploads/media/b003549c5684.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/b003549c5684.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1),
  updated_at = NOW()
WHERE id = 'fb7cf632-32cc-5434-919a-fe39fb0ef3a7'::uuid;
UPDATE public.profiles SET
  username = 'lc-madaarchitectes',
  full_name = 'MADA Architectes',
  profession = 'Architect',
  location = 'Casablanca',
  bio = 'MADA Architects was founded by two young architects who believe that spaces should expand life, not complicate it. Inspired by the Arabic word “مدى” — Mada, meaning horizon, range, and possibility, the studio was born from a shared desire to design w…',
  about_text = 'MADA Architects was founded by two young architects who believe that spaces should expand life, not complicate it. Inspired by the Arabic word “مدى” — Mada, meaning horizon, range, and possibility, the studio was born from a shared desire to design with clarity, intention, and human experience at the center. For us, architecture begins with understanding people — how they move, feel, breathe, and belong. Every line we draw is guided by a simple question: How can this space make life easier, calmer, and more meaningful? Our work blends the precision of architecture with the softness of lived experience. We design with light as a material, with the horizon as a guide, and with simplicity as a quiet act of respect. Whether shaping a home, a public place, or a small interior, we aim to create environments that feel effortless, grounded, and deeply connected to their context. At MADA Architects, we’re not driven by trends or noise. We’re driven by clarity. By purpose. By the belief that minimalism is not emptiness — it is room for life to grow. We build spaces that open possibilities. Spaces that breathe. Spaces that reach their own horizon. This is our Mada. Your Mada. The architecture of what’s possible.',
  phone = '0658200711',
  email = 'lc-madaarchitectes@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003881440000017',
  avatar_url = 'https://lechantier.ma/uploads/media/2bf048a2445d.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/2bf048a2445d.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1),
  updated_at = NOW()
WHERE id = '17a019ab-e9bb-50d1-bf58-7d6a2c89a87d'::uuid;
UPDATE public.profiles SET
