UPDATE public.profiles SET
  username = 'lc-atterra',
  full_name = 'ATTERRA',
  profession = 'Engineering firm',
  location = 'Marrakech',
  bio = 'Installée à Marrakech, ATTERRA a pour ambition de conjuguer exigence technique, innovation et respect du territoire, au service des projets marocains et des dynamiques régionales. 🌿Forte de l’expérience du groupe en France, ATTERRA s’engage dans une…',
  about_text = 'Installée à Marrakech, ATTERRA a pour ambition de conjuguer exigence technique, innovation et respect du territoire, au service des projets marocains et des dynamiques régionales. 🌿Forte de l’expérience du groupe en France, ATTERRA s’engage dans une démarche environnementale exigeante, au cœur de chacun de ses projets. Nous croyons qu’une ingénierie responsable est une ingénierie qui préserve les ressources, valorise les écosystèmes locaux et anticipe les défis climatiques. 🤝 ATTERRA c’est aussi un engagement pour la formation et la montée en compétence des ingénieurs marocains. Nous souhaitons contribuer activement au développement d’un savoir-faire local, ancré dans les réalités du territoire et tourné vers l’innovation durable. 🌍 Cette implantation ouvre un nouveau chapitre pour notre groupe, placé sous le signe de la coopération interculturelle, du développement responsable et de la création de valeur partagée entre la France et le Maroc. 📌 Suivez-nous dans cette aventure, et n’hésitez pas à nous contacter pour collaborer, construire ou simplement échanger autour de l’ingénierie, de l’environnement et des territoires.',
  phone = '+212524458117',
  email = 'vous@exemple.com',
  website_url = 'https://www.atterra.ma',
  ice = '003738757000006',
  avatar_url = 'https://lechantier.ma/uploads/media/55133b1544c9.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/55133b1544c9.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1),
  updated_at = NOW()
WHERE id = '29b2a221-bfd2-5436-aa25-35bead3bf482'::uuid;
UPDATE public.profiles SET
  username = 'lc-atelierszegnounarchi',
