UPDATE public.profiles SET
  username = 'lc-ghanimarchitects',
  full_name = 'GHANIM ARCHITECTS',
  profession = 'Architect',
  location = 'Beni Mellal',
  bio = 'Ghanim Architects est un bureau d’architecture pluridisciplinaire basé à Beni Mellal, fondé par M. Amine Ghanim, architecte et urbaniste passionné et engagé dans le développement durable et le rayonnement territorial. Alliant créativité, rigueur et a…',
  about_text = 'Ghanim Architects est un bureau d’architecture pluridisciplinaire basé à Beni Mellal, fondé par M. Amine Ghanim, architecte et urbaniste passionné et engagé dans le développement durable et le rayonnement territorial. Alliant créativité, rigueur et ancrage local, le bureau intervient dans divers domaines : architecture, urbanisme, design d’intérieur et accompagnement stratégique des projets d’investissement. Notre approche repose sur une écoute attentive des besoins du client, une lecture fine du contexte et une volonté de proposer des réponses architecturales à la fois audacieuses, fonctionnelles et porteuses de sens. Nous attachons une attention particulière à l’intégration paysagère, à la valorisation des ressources locales et à l’impact environnemental de nos projets. Implanté dans la région de Béni Mellal-Khénifra, Ghanim Architects a contribué à de nombreux projets d’envergure dans les secteurs du tourisme, de l’industrie, de la santé et de l’éducation. Notre expertise se traduit par des réalisations sensibles, innovantes et pérennes, inscrites dans une vision contemporaine de l’architecture marocaine. Au-delà de la conception, le bureau accompagne ses clients à chaque étape : études, autorisations, coordination technique, suivi de chantier. Ghanim Architects s’inscrit dans une dynamique de territoire, au service d’une architecture responsable, humaine et résolument tournée vers l’avenir.',
  phone = '0661829662',
  email = 'lc-ghanimarchitects@lechantier.sifarah.local',
  website_url = NULL,
  ice = '002403412000003',
  avatar_url = 'https://lechantier.ma/uploads/media/913726113fa9.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/913726113fa9.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1),
