UPDATE public.profiles SET
  username = 'lc-laazizingenierie',
  full_name = 'LAAZIZ INGENIERIE',
  profession = 'Professionnel BTP',
  location = 'Casablanca',
  bio = 'Le bureau d’études bâtiment est une structure spécialisée dans l’ingénierie, la conception technique et l’accompagnement des projets de construction, de rénovation ou de réhabilitation de bâtiments. Il intervient en amont de tout projet afin d’en gar…',
  about_text = 'Le bureau d’études bâtiment est une structure spécialisée dans l’ingénierie, la conception technique et l’accompagnement des projets de construction, de rénovation ou de réhabilitation de bâtiments. Il intervient en amont de tout projet afin d’en garantir la faisabilité, la sécurité, la performance et la conformité aux normes en vigueur. Grâce à une équipe pluridisciplinaire, notre bureau d’études assure la coordination des différentes phases techniques d’un projet : études préliminaires, dimensionnement des structures, plans d’exécution, études thermiques, acoustiques, ou encore la gestion des fluides (CVC, plomberie, électricité). Nos missions couvrent plusieurs domaines : -Études de faisabilité et diagnostics techniques -Conception des structures béton, charpente -Suivi et contrôle technique sur chantier Nous accompagnons nos clients (maîtres d’ouvrage, architectes, collectivités, promoteurs ou entreprises générales) tout au long du projet, depuis la phase d’esquisse jusqu’à la réception des travaux.',
  phone = '0668604464',
  email = 'lc-laazizingenierie@lechantier.sifarah.local',
