UPDATE public.profiles SET
  username = 'lc-gicetudes',
  full_name = 'Gic Études',
  profession = 'Engineering firm',
  location = 'Témara',
  bio = 'GIC Études (Groupe d’Ingénierie de Construction) est un bureau d’études techniques agréé par l’État, spécialisé dans le calcul de structures, les études techniques et le suivi de projets de construction. Nous mettons notre expertise au service des ar…',
  about_text = 'GIC Études (Groupe d’Ingénierie de Construction) est un bureau d’études techniques agréé par l’État, spécialisé dans le calcul de structures, les études techniques et le suivi de projets de construction. Nous mettons notre expertise au service des architectes, entrepreneurs et institutions pour garantir des ouvrages sûrs, performants et durables. Parmi nos réalisations, nous avons assuré l’étude et le suivi de projets variés tels que le refuge pour animaux de Tanger, un internat et un centre de santé à chefchaoen, ainsi que plusieurs établissements scolaires à Tanger. Nous avons également accompagné des architectes dans la coordination et le suivi de chantiers d’envergure tels que la réhabilitation de Plaza Toro, la reconversion de l’ancien marché de gros de Tanger, et encore des résidences hôtelières modernes. GIC Études se distingue par sa rigueur technique, son sens du détail architectural et son engagement envers la qualité et la conformité réglementaire. Grâce à une équipe d’ingénieurs passionnés et à l’utilisation d’outils de modélisation avancés, nous offrons des solutions économiques, innovantes et adaptées à chaque projet, du concept jusqu’à la réalisation.',
  phone = '0628494153',
  email = 'lc-gicetudes@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003129871000077',
  avatar_url = 'https://lechantier.ma/uploads/media/80e9c7b40fdb.webp',
