UPDATE public.profiles SET
  username = 'lc-geneltec',
  full_name = 'Geneltec',
  profession = 'Électricien',
  location = 'Mohammedia',
  bio = 'GENELTEC – Électricité & Smart Home Solutions GENELTEC est une entreprise marocaine spécialisée dans les installations électriques complètes pour villas, bâtiments résidentiels et projets commerciaux. Nous offrons des solutions modernes et intelligen…',
  about_text = 'GENELTEC – Électricité & Smart Home Solutions GENELTEC est une entreprise marocaine spécialisée dans les installations électriques complètes pour villas, bâtiments résidentiels et projets commerciaux. Nous offrons des solutions modernes et intelligentes pour rendre chaque espace plus sûr, plus efficace et plus confortable. Nos domaines d’expertise : ⚡ Électricité du bâtiment et industrielle – Installation, rénovation et maintenance complètes 🏠 Smart Home – Commande intelligente de l’éclairage, volets, climatisation, et sécurité 🔒 Serrures et portes connectées WiFi – Ouverture par empreinte, code ou carte 📷 Caméras & visiophones – Surveillance, interphonie et contrôle d’accès ☀️ Énergie solaire & bornes de recharge – Solutions écologiques et durables Chez GENELTEC, nous combinons savoir-faire technique, technologie moderne et engagement envers la qualité pour garantir la satisfaction de nos clients. Basés à Casablanca, nous intervenons dans tout le Maroc, en accompagnant architectes, promoteurs, et particuliers dans leurs projets.',
  phone = '+212662129067',
  email = 'contact@geneltec.ma',
