UPDATE public.profiles SET
  username = 'lc-effinex',
  full_name = 'EFFINEX',
  profession = 'Électricien',
  location = 'Casablanca',
  bio = 'EFFINEX | Expertise, Innovation & Maintenance en Infrastructures Réseaux Bienvenue sur le profil officiel d''EFFINEX, votre partenaire stratégique basé à Casablanca, spécialisé dans l’installation et la maintenance des infrastructures télécoms et rése…',
  about_text = 'EFFINEX | Expertise, Innovation & Maintenance en Infrastructures Réseaux Bienvenue sur le profil officiel d''EFFINEX, votre partenaire stratégique basé à Casablanca, spécialisé dans l’installation et la maintenance des infrastructures télécoms et réseaux. Forts d''une alliance unique entre 35 ans d''expérience terrain (issue de l''opérateur historique) et une vision moderne axée sur l''innovation, nous accompagnons les opérateurs, PME et administrations dans la performance de leurs systèmes. Nos domaines d’intervention : • Audit & Ingénierie : État des lieux détaillé, tests de performance et conception de solutions sur mesure (études techniques et plans d’exécution). • Infrastructures & Déploiement : Installation de fibre optique (FO), câblage cuivre (VDI) et aménagement de baies de brassage selon les normes les plus strictes. • Intégration d’Équipements Actifs : Configuration de switchs, routeurs, réseaux Wi-Fi et systèmes de vidéosurveillance. • Maintenance & Support : Interventions curatives rapides et contrats préventifs pour garantir la continuité de vos services. • Distribution & Négoce : Fourniture d''équipements de pointe et outillage certifié. Pourquoi nous choisir ? • Réactivité : Équipes mobiles et autonomes avec flotte de véhicules propre. • Fiabilité : Contrôle qualité systématique et traçabilité des opérations. • Expertise : Une équipe certifiée alliant savoir-faire technique et optimisation des ressources. Prêt à moderniser vos infrastructures ? Contactez-nous.',
  phone = '+212661821123',
  email = 'contact@effinex.ma',
  website_url = 'https://effinex.ma/',
  ice = '003835779000091',
  avatar_url = 'https://lechantier.ma/uploads/media/6bba739b887d.webp',
