UPDATE public.profiles SET
  username = 'lc-orca-lum',
  full_name = 'Orca Lum',
  profession = 'Aluminium',
  location = 'Casablanca',
  bio = 'ORCA LUM – Profil de société Secteur d’activité : Construction et menuiserie industrielle Sous-secteurs : Menuiserie aluminium : portes, fenêtres, façades, cloisons, volets, baies vitrées sur mesure Portes isothermes et solutions techniques pour hôpi…',
  about_text = 'ORCA LUM – Profil de société Secteur d’activité : Construction et menuiserie industrielle Sous-secteurs : Menuiserie aluminium : portes, fenêtres, façades, cloisons, volets, baies vitrées sur mesure Portes isothermes et solutions techniques pour hôpitaux, hôtels, industries agroalimentaires et chambres froides Fabrication et installation sur mesure avec service après-vente Solutions pour bâtiments commerciaux, industriels et résidentiels Description générale : Orca Lum est une entreprise marocaine spécialisée dans la conception, la fabrication et l’installation de portes et menuiseries en aluminium, ainsi que dans les solutions techniques isothermes pour les secteurs professionnels et industriels. Nous fournissons des produits durables, esthétiques et performants, adaptés aux besoins des hôpitaux, hôtels, industries alimentaires et projets de construction variés. Notre objectif est d’offrir à nos clients des solutions fiables et sur mesure, alliant qualité, design, sécurité et performance thermique, tout en assurant un suivi technique complet avant et après installation. Nos services : Menuiserie aluminium sur mesure : portes, fenêtres, façades, cloisons, volets, baies vitrées Portes isothermes pour hôpitaux, hôtels et industries agroalimentaires Installation professionnelle avec respect des normes techniques et de sécurité Accompagnement client complet : étude de projet, fabrication, pose, maintenance et service après-vente Solutions pour tous types de bâtiment',
  phone = '+212661115628',
  email = 'contact@orca-lum.placeholder.ma',
  website_url = 'https://orcalum.com/',
  ice = '003442538000075',
  avatar_url = 'https://lechantier.ma/uploads/media/4eaefc891bab.webp',
