UPDATE public.profiles SET
  username = 'lc-gadimat',
  full_name = 'GADIMAT',
  profession = 'Construction materials',
  location = 'Agadir',
  bio = 'Gadimat, Société Anonyme au capital de 3o millions de Dirhams, créée en 1977 et basée à Agadir dans le Sud du pays, est associée au Groupe Robelbois, leader importateur de bois, panneaux & matériaux de construction au Maroc depuis plusieurs décennies…',
  about_text = 'Gadimat, Société Anonyme au capital de 3o millions de Dirhams, créée en 1977 et basée à Agadir dans le Sud du pays, est associée au Groupe Robelbois, leader importateur de bois, panneaux & matériaux de construction au Maroc depuis plusieurs décennies. Gadimat possède une part de marché de près de 10% dans tout le Royaume et est largement dominante dans le Sud où sa part de marché approche les 50%. Gadimat dispose d’une surface de 30 000 m2 permettant d’entreposer les 80 000 m3 de marchandises importées annuellement. La large flotte de camions permet d’acheminer la marchandise dans tout le Maroc. Les équipes de Gadimat sont sans cesse en quête de progrès et ont pour priorité « l’expérience client ». L’ensemble des 85 personnes responsables du succès de la société fournit des efforts constants afin de proposer à notre clientèle variée tous les produits dont elle a besoin, tout au long de l’année, à des tarifs compétitifs.',
  phone = '0666111551',
  email = 'lc-gadimat@lechantier.sifarah.local',
  website_url = NULL,
