UPDATE public.profiles SET
  username = 'lc-beton-cire-maroc',
  full_name = 'BETON CIRE MAROC',
  profession = 'Wall covering',
  location = 'Rabat',
  bio = 'Béton Ciré Maroc est une entreprise spécialisée dans la création et l’application de revêtements décoratifs en béton ciré, destinés aux particuliers et aux professionnels à la recherche d’un design moderne, épuré et durable. Notre mission est de tran…',
  about_text = 'Béton Ciré Maroc est une entreprise spécialisée dans la création et l’application de revêtements décoratifs en béton ciré, destinés aux particuliers et aux professionnels à la recherche d’un design moderne, épuré et durable. Notre mission est de transformer chaque espace en un lieu unique, où la matière brute devient élégance, sobriété et confort visuel. Grâce à une maîtrise artisanale et à des techniques modernes, nous réalisons des finitions sur mesure pour les sols, murs, salles de bains, cuisines, façades et piscines. Le béton ciré que nous appliquons est reconnu pour sa résistance exceptionnelle, son entretien facile et sa capacité à s’intégrer harmonieusement dans tous les styles — du minimalisme contemporain au charme rustique marocain. Chez Béton Ciré Maroc, nous plaçons la qualité et la satisfaction de nos clients au cœur de chaque projet. Chaque chantier est étudié avec soin afin d’assurer une application parfaite, une durabilité maximale et un rendu esthétique irréprochable. Nous intervenons sur tout le territoire marocain, aussi bien pour les maisons individuelles que pour les projets professionnels : hôtels, restaurants, showrooms, villas ou bureaux. Notre vision est simple : allier l’art, la technique et la passion pour offrir des surfaces uniques, à la fois fonctionnelles et inspirantes. Avec Béton Ciré Maroc, votre espace devient une œuvre d’art vivante.',
  phone = '+212662812519',
  email = 'contact@beton-cire-maroc.placeholder.ma',
  website_url = 'https://www.betonciremaroc.com',
  ice = '000047467000052',
  avatar_url = 'https://lechantier.ma/uploads/media/7ee15a86b17f.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/7ee15a86b17f.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1),
  updated_at = NOW()
WHERE id = '80bf6c4d-e3ad-5ad0-abb2-8ebd58094a41'::uuid;
UPDATE public.profiles SET
  username = 'lc-koudiwood',
