UPDATE public.profiles SET
  username = 'lc-redainnovatesolutions',
  full_name = 'Reda innovate solutions',
  profession = 'Professionnel BTP',
  location = 'Casablanca',
  bio = '\[REDA INNOVATE SOLUTION\] est une société spécialisée dans les travaux de résine industrielle, notamment dans la réparation et le revêtement des sols, avec une expertise particulière dans les parkings souterrains, les entrepôts, les bâtiments indust…',
