UPDATE public.profiles SET
  username = 'lc-aharkousaziz',
  full_name = 'aharkous aziz',
  profession = 'Painting',
  location = 'Marrakech',
  bio = 'Je m’appelle Aziz , peintre professionnel avec 6 ans d’expérience dans le domaine de la peinture et de la décoration. Je dirige une équipe qualifiée de peintres, reconnue pour son travail de qualité, sa précision et son souci du détail. Au fil des an…',
  about_text = 'Je m’appelle Aziz , peintre professionnel avec 6 ans d’expérience dans le domaine de la peinture et de la décoration. Je dirige une équipe qualifiée de peintres, reconnue pour son travail de qualité, sa précision et son souci du détail. Au fil des années, nous avons réalisé de nombreux projets — notamment dans des hôtels, riads, toits-terrasses, restaurants et maisons privées — en offrant toujours des résultats durables et esthétiques, conformes aux plus hauts standards. Nous sommes spécialisés dans la peinture intérieure et extérieure, la préparation des murs et les finitions décoratives, en utilisant les meilleurs matériaux et techniques pour garantir un rendu parfait à chaque fois. Notre mission est de transformer les espaces grâce à la couleur et au savoir-faire, en créant des environnements propres, élégants et accueillants pour chaque client. My name is Aziz , a professional painter with 6 years of experience in the painting and decorating industry. I lead a skilled team of painters known for our commitment to quality, precision, and attention to detail. Over the years, we have completed a wide range of projects — including hotels, riads, rooftops, restaurants, and private homes — always delivering beautiful, long-lasting results that meet the highest standards. We specialize in interior and exterior painting, wall preparation, and decorative finishes, using only the best materials and modern techniques to ensure a perfect finish every time.',
  phone = '+212773227340',
  email = 'lc-aharkousaziz@lechantier.sifarah.local',
  website_url = NULL,
  ice = NULL,
  avatar_url = 'https://lechantier.ma/uploads/media/06692ead8c26.webp',
