UPDATE public.profiles SET
  username = 'lc-friyahya',
  full_name = 'Fri Yahya',
  profession = 'Wall covering installation',
  location = 'Salé',
  bio = 'معلم وحرفي الزليج البلدي الفاسي ​أنا يحيى فر حرفي ومعلم في فن الزليج البلدي الفاسي الأصيل، وهو أحد أعرق وأجمل فنون الديكور التقليدي في المغرب. أحمل في يدي خبرة تمتد لأكثر من 3 سنوات، ورثتها جيلًا بعد جيل، مما جعلني أتقن كل مراحل هذه الحرفة العريقة. ​…',
  about_text = 'معلم وحرفي الزليج البلدي الفاسي ​أنا يحيى فر حرفي ومعلم في فن الزليج البلدي الفاسي الأصيل، وهو أحد أعرق وأجمل فنون الديكور التقليدي في المغرب. أحمل في يدي خبرة تمتد لأكثر من 3 سنوات، ورثتها جيلًا بعد جيل، مما جعلني أتقن كل مراحل هذه الحرفة العريقة. ​ما أقدمه: ​الزليج اليدوي الأصيل: متخصص في تصميم وتنفيذ ألواح الزليج الفاسي بالكامل يدويًا، التركيب النهائي لإنشاء لوحات هندسية معقدة ومذهلة. ​الحفاظ على التراث: ألتزم باستخدام التقنيات والمواد التقليدية للحفاظ على الجودة التاريخية والجمالية المميزة للزليج الفاسي. ​تصميمات فريدة: سواء كانت تصاميم كلاسيكية مثل التويزات والمشابك، أو تنفيذ تصميمات عصرية بلمسة تقليدية، أسعى دائمًا لتقديم قطع فنية فريدة تعكس ذوق العميل وروح المكان. ​الخبرة والمشاريع: عملت على تزيين \[اذكر أمثلة: رياضات، مساجد، فنادق، قصور خاصة\] داخل وخارج المغرب، مع التركيز على الدقة المتناهية والاهتمام بأدق التفاصيل الهندسية. ​الشغف والرسالة: ​الزليج ليس مجرد بلاط، بل هو تاريخ وفلسفة وهندسة تتجسد في كل قطعة. شغفي هو نقل هذا الفن من الأجداد إلى الأجيال الجديدة، وإضافة لمسة من سحر الحرفية المغربية إلى كل مساحة عمل عليها. ​مستعد للعمل على مشاريعكم القادمة وإضفاء لمسة الجمال الفاسي الأصيل على مساحتكم. ​للتواصل والاستفسار: ​\[+212608827108\] ​\[[\[email protected\]](https://lechantier.ma/cdn-cgi/l/email-protection)\]',
  phone = '+212608827108',
  email = 'lc-friyahya@lechantier.sifarah.local',
  website_url = 'https://lechantier.ma/cdn-cgi/l/email-protection',
  ice = NULL,
  avatar_url = 'https://lechantier.ma/uploads/media/d086c62d7bf1.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/d086c62d7bf1.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1),
  updated_at = NOW()
WHERE id = 'dbb0d14a-aea1-534d-b1db-f7a33bb7f874'::uuid;
