UPDATE public.profiles SET
  username = 'lc-bricolink',
  full_name = 'Bricolink',
  profession = 'Hardware',
  location = 'Casablanca',
  bio = 'Bricolink est une entreprise spécialisée dans la distribution de quincaillerie pour cuisines, dédiée aux professionnels du bâtiment, aux artisans, ainsi qu’aux particuliers exigeants. Nous proposons une large gamme de produits de qualité allant des c…',
  about_text = 'Bricolink est une entreprise spécialisée dans la distribution de quincaillerie pour cuisines, dédiée aux professionnels du bâtiment, aux artisans, ainsi qu’aux particuliers exigeants. Nous proposons une large gamme de produits de qualité allant des charnières, coulisses, poignées, systèmes de tiroirs, fixations, jusqu’aux accessoires d’aménagement intérieur. Notre mission est de fournir des solutions fiables, durables et esthétiques qui répondent aux besoins des cuisinistes, menuisiers et bricoleurs avertis. Grâce à un stock bien géré et à des partenariats solides avec les plus grandes marques du secteur, nous garantissons des livraisons rapides et un excellent rapport qualité-prix. Chez Bricolink, le service client est au cœur de notre engagement. Nous accompagnons nos clients dans leurs projets avec des conseils techniques personnalisés, des fiches produits détaillées, et une assistance réactive. Que vous soyez en phase de conception, d’installation ou de rénovation, notre équipe est là pour vous aider à trouver les meilleures solutions. Bricolink, c’est l’alliance entre expertise technique, service de proximité et passion du métier. Rejoignez notre réseau de clients satisfaits et donnez vie à vos projets de cuisine avec la quincaillerie qu’il vous faut.',
  phone = '+212687385332',
  email = 'lc-bricolink@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003579119000037',
  avatar_url = 'https://lechantier.ma/uploads/media/6d914e35a662.webp',
