UPDATE public.profiles SET
  username = 'lc-quincaillerieanasse',
  full_name = 'Quincaillerie Anasse',
  profession = 'Hardware',
  location = 'Casablanca',
  bio = 'Quincaillerie Anasse, Votre partenaire de confiance pour chaque projet immobilier. Depuis plus de 15 ans, Quincaillerie Anasse accompagne les professionnels du bâtiment et les promoteurs immobiliers à chaque étape de leurs projets. Située au 490 Boul…',
  about_text = 'Quincaillerie Anasse, Votre partenaire de confiance pour chaque projet immobilier. Depuis plus de 15 ans, Quincaillerie Anasse accompagne les professionnels du bâtiment et les promoteurs immobiliers à chaque étape de leurs projets. Située au 490 Boulevard El Fida, Casablanca, notre quincaillerie met à votre disposition un large choix de produits adaptés à tous les niveaux de finition : économique, moyen et luxe. Nous proposons une vaste gamme comprenant la visserie et les chaînes d’extension, les serrures et verrous, les charnières, les glissières pour tiroirs, les poignées et béquilles, les ferme-portes, les amortisseurs, les outils de mesure, les distributeurs, les supports d’étagères et bien d’autres articles sélectionnés pour leur qualité et leur fiabilité. Notre différence réside dans notre approche humaine et experte : nous ne nous contentons pas de vendre des produits, nous conseillons nos clients pour les aider à faire le meilleur choix en matière de rapport qualité/prix. Chaque projet est unique, et notre mission est de vous fournir les solutions les plus adaptées à vos besoins techniques, esthétiques et budgétaires. Que vous soyez à Casablanca ou ailleurs au Maroc, nous assurons un service rapide, fiable et à l’écoute de vos exigences. 📞 Contactez-nous dès aujourd’hui ou venez directement nous rendre visite à notre magasin pour découvrir la qualité de nos produits et le sérieux de notre accompagnement.',
  phone = '+212663845419',
  email = 'lc-quincaillerieanasse@lechantier.sifarah.local',
  website_url = NULL,
  ice = '121212121212121',
  avatar_url = 'https://lechantier.ma/uploads/media/2c74f89b50c1.webp',
