UPDATE public.profiles SET
  username = 'lc-acm',
  full_name = 'ACM',
  profession = 'Interior design',
  location = 'Marrakech',
  bio = 'ACM – Aura Construction Maroc Chez ACM, nous sommes spécialisés dans la rénovation et la finition intérieure et extérieure de maisons, villas, appartements, commerces et bureaux. Notre mission est de transformer chaque espace en alliant qualité, esth…',
