UPDATE public.profiles SET
  username = 'lc-nadwork',
  full_name = 'NADWORK',
  profession = 'Interior design',
  location = 'Rabat',
  bio = 'Depuis plus de trente ans, NADWORK s''impose comme une référence dans les domaines de l’aménagement, de l’architecture, du design d’intérieur et de la construction. Société pluridisciplinaire, NADWORK réunit sous un même nom l''expertise, la créativité…',
  about_text = 'Depuis plus de trente ans, NADWORK s''impose comme une référence dans les domaines de l’aménagement, de l’architecture, du design d’intérieur et de la construction. Société pluridisciplinaire, NADWORK réunit sous un même nom l''expertise, la créativité et la rigueur technique, pour offrir à ses clients des projets sur mesure, alliant fonctionnalité, esthétisme et durabilité. Fort d’un savoir-faire consolidé au fil des décennies, notre bureau accompagne ses clients – particuliers, entreprises ou institutions – dans la conception et la réalisation de leurs espaces. De la phase d’étude architecturale à la livraison clé en main, en passant par le suivi de chantier, chaque projet est pensé dans sa globalité, avec une attention particulière portée aux détails, aux matériaux et à l’harmonie des volumes. Notre approche intégrée permet d’assurer une parfaite cohérence entre l’enveloppe bâtie, l’agencement intérieur et les usages spécifiques de chaque lieu. NADWORK s’appuie sur une équipe expérimentée et passionnée, engagée à transformer chaque idée en un espace unique, durable et innovant.',
  phone = '0662114655',
  email = 'lc-nadwork@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003324187000081',
  avatar_url = 'https://lechantier.ma/uploads/media/78d0daefd209.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/78d0daefd209.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1),
  updated_at = NOW()
WHERE id = '7e9dc0d2-f6a3-53d4-85d9-75dc003390ee'::uuid;
