UPDATE public.profiles SET
  username = 'lc-mondibat',
  full_name = 'Mondibat',
  profession = 'Interior design',
  location = 'Casablanca',
  bio = '🏗️ Mondibat – Votre partenaire travaux tous corps d’état au Maroc. Chez Mondibat, nous sommes plus qu’une simple entreprise de rénovation. Nous sommes un partenaire de confiance, capable de prendre en charge l’ensemble de vos projets de construction,…',
  about_text = '🏗️ Mondibat – Votre partenaire travaux tous corps d’état au Maroc. Chez Mondibat, nous sommes plus qu’une simple entreprise de rénovation. Nous sommes un partenaire de confiance, capable de prendre en charge l’ensemble de vos projets de construction, d’aménagement et de transformation – du sol au plafond, de la structure jusqu’à la touche déco finale. 👷‍♂️ Notre équipe polyvalente, composée d’artisans qualifiés, de techniciens et de designers, intervient sur tous les corps de métier pour vous offrir un service clé en main, professionnel et sans mauvaises surprises. 🔧 Nos domaines d’intervention : • Gros œuvre et second œuvre : électricité, plomberie, climatisation, isolation, étanchéité, domotique • Aménagement intérieur : pose de cuisine, peinture, carrelage, parquet, faux plafond, revêtement mural et sol • Finitions techniques : menuiserie, aluminium, vitres, fenêtres, portes, volets • Aménagement extérieur : piscine, terrasse, véranda, charpente métallique • Services complémentaires : infographie 3D, maquette, architecture d’intérieur, nettoyage de fin de chantier 🛠️ Grâce à notre approche globale, vous n’avez plus besoin de gérer plusieurs prestataires : Mondibat s’occupe de tout, dans le respect des délais, du budget et de la qualité attendue. 📞 Contactez-nous pour un devis gratuit et personnalisé. Avec Mondibat, vos idées prennent vie dans les meilleures conditions.',
  phone = '0662853525',
  email = 'lc-mondibat@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003226594000087',
  avatar_url = 'https://lechantier.ma/logo.svg',
  cover_photo_url = 'https://lechantier.ma/uploads/media/8ea7d53c4920.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '5.2.2' LIMIT 1),
