UPDATE public.profiles SET
  username = 'lc-ouvragecontractor',
  full_name = 'Ouvrage Contractor',
  profession = 'Structural work',
  location = 'Marrakech',
  bio = 'Ouvrage Contractor est une entreprise spécialisée dans le bâtiment, les travaux publics et les ouvrages de construction, basée à Marrakech. Forte d’une expertise éprouvée dans le secteur, notre société intervient auprès des particuliers, entreprises…',
  about_text = 'Ouvrage Contractor est une entreprise spécialisée dans le bâtiment, les travaux publics et les ouvrages de construction, basée à Marrakech. Forte d’une expertise éprouvée dans le secteur, notre société intervient auprès des particuliers, entreprises privées et administrations publiques, en garantissant qualité, respect des délais et maîtrise des coûts. Notre mission est d’apporter des solutions fiables, innovantes et adaptées aux besoins de nos clients, tout en respectant les normes de sécurité et les standards de construction en vigueur. Domaines d’intervention : • Travaux de construction et gros œuvre • Aménagements et finitions • Rénovation et réhabilitation de bâtiments • Projets publics et privés • Suivi, pilotage et coordination de chantiers Nos atouts : • Une équipe compétente et expérimentée • Un réseau de partenaires techniques et financiers • Une approche centrée sur la satisfaction client • Un engagement fort envers la qualité et la durabilité Grâce à notre savoir-faire et notre professionnalisme, Ouvrage Contractor s’impose comme un acteur de confiance dans le domaine de la construction et de l’aménagement au Maroc.',
  phone = '0661554509',
  email = 'lc-ouvragecontractor@lechantier.sifarah.local',
  website_url = NULL,
  ice = '001633735000002',
  avatar_url = 'https://lechantier.ma/uploads/media/4eab37ca783d.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/4eab37ca783d.webp',
  profile_type = 'enterprise',
