UPDATE public.profiles SET
  username = 'lc-egmer',
  full_name = 'EGMER',
  profession = 'Structural work',
  location = 'Casablanca',
  bio = 'Nous sommes une entreprise marocaine spécialisée dans l’agencement, l’aménagement, la construction et les travaux divers, offrant des solutions complètes et sur mesure pour répondre aux besoins variés de nos clients. Avec plus de 25 ans d’expérience,…',
  about_text = 'Nous sommes une entreprise marocaine spécialisée dans l’agencement, l’aménagement, la construction et les travaux divers, offrant des solutions complètes et sur mesure pour répondre aux besoins variés de nos clients. Avec plus de 25 ans d’expérience, nous nous sommes imposés comme un acteur de confiance dans le secteur du bâtiment et des travaux publics au Maroc. Depuis notre création, nous nous engageons à fournir des réalisations de haute qualité, respectant les normes techniques et les délais convenus, tout en intégrant des solutions innovantes et esthétiques adaptées aux exigences des projets modernes. Nos domaines d’intervention couvrent : L’agencement et l’aménagement intérieur et extérieur : conception, finition et optimisation des espaces pour professionnels et particuliers. La construction : réalisation de bâtiments neufs, extensions et réhabilitations. Les travaux divers : interventions multiservices dans le cadre de chantiers publics et privés. Nous mettons à profit un savoir-faire reconnu, une équipe qualifiée et des partenariats solides pour garantir la satisfaction totale de nos clients et contribuer au développement durable des infrastructures au Maroc.',
  phone = '0668787444',
  email = 'lc-egmer@lechantier.sifarah.local',
  website_url = NULL,
  ice = '000198408000003',
  avatar_url = 'https://lechantier.ma/uploads/media/826aa878008d.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/826aa878008d.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1),
  updated_at = NOW()
WHERE id = 'ddf84f8f-698f-5704-99c9-7de79e171734'::uuid;
