UPDATE public.profiles SET
  username = 'lc-lahlou-workers',
  full_name = 'LAHLOU WORKERS',
  profession = 'Structural work',
  location = 'Agadir',
  bio = 'LAHLOU WORKERS, entreprise de construction fondée en 2022, s''appuie sur une solide expérience internationale dans la réalisation d''ouvrages de prestige. Spécialisés dans les hôtels de luxe, complexes résidentiels haut de gamme et immeubles de bureaux…',
  about_text = 'LAHLOU WORKERS, entreprise de construction fondée en 2022, s''appuie sur une solide expérience internationale dans la réalisation d''ouvrages de prestige. Spécialisés dans les hôtels de luxe, complexes résidentiels haut de gamme et immeubles de bureaux, nous avons développé une expertise reconnue auprès d''une clientèle internationale exigeante. Notre savoir-faire s''étend de la conception à la livraison, en maîtrisant les standards internationaux les plus élevés. Chaque projet reflète notre engagement envers l''excellence, alliant techniques de construction innovantes, matériaux nobles et finitions irréprochables. Aujourd''hui, LAHLOU WORKERS a une ambition claire : mettre notre expertise internationale au service de nos clients. Cette démarche s''inscrit dans notre volonté de contribuer au développement du secteur immobilier national, en apportant les standards de qualité et d''innovation que nous avons perfectionnés à l''international. LAHLOU WORKERS incarne ainsi le pont entre l''excellence internationale et l''ancrage local, offrant à nos clients marocains le meilleur de notre expérience mondiale pour des projets d''exception sur le territoire national.',
  phone = '+212661728217',
  email = 'lahlou.workers@gmail.com',
  website_url = 'https://lahlou-workers.com/',
  ice = '003157258000059',
  avatar_url = 'https://lechantier.ma/uploads/media/4b59b65ecf71.webp',
