UPDATE public.profiles SET
  username = 'lc-sfgiesarlau',
  full_name = 'SFGIE SARL AU',
  profession = 'Structural work',
  location = 'Marrakech',
  bio = 'STE SFGIE SARL AU est une entreprise spécialisée dans les travaux de construction, de génie civil et de rénovation. Forte d’une équipe expérimentée et qualifiée, notre société intervient dans divers secteurs : bâtiments résidentiels, industriels, com…',
  about_text = 'STE SFGIE SARL AU est une entreprise spécialisée dans les travaux de construction, de génie civil et de rénovation. Forte d’une équipe expérimentée et qualifiée, notre société intervient dans divers secteurs : bâtiments résidentiels, industriels, commerciaux, travaux publics, assainissement, VRD (Voirie et Réseaux Divers), ainsi que la fabrication et pose d’ouvrages en béton (regards, buses, dalles, etc.). Notre engagement repose sur la qualité du travail, le respect des délais, la sécurité sur les chantiers et la satisfaction de nos clients. Nous accompagnons nos partenaires dans toutes les étapes de leurs projets, de l’étude à la réalisation, en proposant des solutions techniques adaptées et économiques. Grâce à notre savoir-faire, notre sérieux et notre souci du détail, nous avons su gagner la confiance de nombreux clients, publics comme privés.',
  phone = '0667843754',
  email = 'lc-sfgiesarlau@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003399614000067',
  avatar_url = 'https://lechantier.ma/uploads/media/eb73c2d929df.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/eb73c2d929df.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1),
