WHERE id = '4cb2fb13-71c1-5666-b30a-a817933e37c5'::uuid;
UPDATE public.profiles SET
  username = 'lc-f1travaux',
  full_name = 'F1 TRAVAUX',
  profession = 'Structural work',
  location = 'El Jadida',
  bio = 'F1 Travaux est une entreprise spécialisée dans le domaine de la construction et des travaux publics (BTP), située à El Jadida. Forte de 7 années d''expérience, notre société s''est imposée comme un acteur clé sur le marché grâce à son expertise et son…',
  about_text = 'F1 Travaux est une entreprise spécialisée dans le domaine de la construction et des travaux publics (BTP), située à El Jadida. Forte de 7 années d''expérience, notre société s''est imposée comme un acteur clé sur le marché grâce à son expertise et son savoir-faire dans la réalisation de projets d''envergure, tant dans le secteur public que privé. Sous la direction d''un professionnel avec 25 ans d’expérience dans l’industrie de la construction, F1 Travaux met un accent particulier sur la qualité, la sécurité et le respect des délais. Nous avons achevé de nombreux projets, allant des infrastructures publiques aux bâtiments privés, en passant par des projets de rénovation et d’aménagement. Notre entreprise est reconnue pour son engagement à fournir des solutions sur mesure, adaptées aux besoins spécifiques de chaque client. Nous mettons à disposition une équipe qualifiée et expérimentée qui travaille avec rigueur et passion, en utilisant des matériaux de qualité et des technologies de pointe. Chez F1 Travaux, nous mettons un point d''honneur à offrir des prestations conformes aux normes et aux exigences les plus strictes du secteur, tout en garantissant une relation de confiance avec nos clients. Que vous soyez un particulier, une collectivité ou un acteur du secteur privé, F1 Travaux est votre partenaire de choix pour mener à bien vos projets de construction dans les meilleures conditions.',
  phone = '0661241166',
  email = 'lc-f1travaux@lechantier.sifarah.local',
  website_url = NULL,
  ice = '002149340000010',
  avatar_url = 'https://lechantier.ma/uploads/media/7feaf0d6d549.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/7feaf0d6d549.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1),
  updated_at = NOW()
WHERE id = 'ccf466b4-6e4d-5563-b813-68b9f0d1af5d'::uuid;
