UPDATE public.profiles SET
  username = 'lc-constravium',
  full_name = 'Constravium',
  profession = 'Structural work',
  location = 'Agadir',
  bio = 'Constravium est une entreprise de Bâtiment et Travaux Publics basée à Agadir, fondée par deux professionnels passionnés du secteur : un ingénieur en génie civil et un technicien spécialisé. Forts d’une solide expérience acquise au sein de bureaux d’é…',
  about_text = 'Constravium est une entreprise de Bâtiment et Travaux Publics basée à Agadir, fondée par deux professionnels passionnés du secteur : un ingénieur en génie civil et un technicien spécialisé. Forts d’une solide expérience acquise au sein de bureaux d’études techniques et de contrôle qualité, nous mettons notre expertise au service de projets de construction fiables, durables et parfaitement encadrés. Notre entreprise intervient dans plusieurs domaines clés : Gros œuvre et second œuvre Travaux de finition intérieure et extérieure Aménagements de bâtiments Suivi et gestion de projets de construction Assistance complète pour l’obtention des Permis de construire Préparation de plans techniques et de dossiers administratifs Chez Constravium, nous allions la rigueur technique à une approche de proximité avec nos clients. Nous nous engageons à respecter les délais, à garantir la qualité de chaque prestation et à proposer des solutions innovantes adaptées aux exigences du marché. Notre mission : bâtir avec confiance, efficacité et transparence, tout en assurant un accompagnement professionnel du début à la fin de chaque chantier.',
  phone = '0664000002',
  email = 'lc-constravium@lechantier.sifarah.local',
