UPDATE public.profiles SET
  username = 'lc-stellarconstruction',
  full_name = 'STELLAR construction',
  profession = 'Structural work',
  location = 'Tétouan',
  bio = 'Nous sommes STELLAR Construction, une entreprise spécialisée dans le secteur du bâtiment et des travaux publics. Notre vision est d''apporter constance, lumière et ambition à chacun de nos projets. Nous nous engageons à offrir des solutions innovantes…',
  about_text = 'Nous sommes STELLAR Construction, une entreprise spécialisée dans le secteur du bâtiment et des travaux publics. Notre vision est d''apporter constance, lumière et ambition à chacun de nos projets. Nous nous engageons à offrir des solutions innovantes et durables, avec l''ambition que chaque réalisation brille par sa qualité et son impact. Nos domaines d''expertise couvrent trois aspects principaux : Travaux de Bâtiment : Cela inclut les travaux de gros œuvre, la rénovation et la réhabilitation, ainsi que les travaux de finition. Travaux Publics : Nous réalisons des canalisations d''eau potable ou d''assainissement, des ouvrages d''art, et des travaux de voirie (VRD). Travaux Spécialisés : Nous proposons également l''aménagement extérieur, la construction et l''aménagement de piscines, et l''aménagement de locaux commerciaux. Notre entreprise est dirigée par Mohammed Sekkal, qui apporte plus de 25 ans d''expérience dans le secteur du bâtiment et des travaux publics. Sa carrière est bâtie sur l''excellence et un savoir-faire qu''il met aujourd''hui au service de projets ambitieux et à forte valeur ajoutée chez STELLAR Construction. Nous sommes passionnés par notre métier et dédiés à la réussite de chaque projet.',
  phone = '0645255255',
  email = 'lc-stellarconstruction@lechantier.sifarah.local',
  website_url = NULL,
  ice = '003441469000032',
  avatar_url = 'https://lechantier.ma/uploads/media/b1e4699fe172.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/b1e4699fe172.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1),
  updated_at = NOW()
WHERE id = 'a08d943d-f529-5f23-add1-a3aabe71d4a4'::uuid;
