UPDATE public.profiles SET
  username = 'lc-acero-building-systems',
  full_name = 'ACERO BUILDING SYSTEMS',
  profession = 'Installation de charpente métallique',
  location = 'Casablanca',
  bio = 'Acero Building Systems (Acero) propose des solutions complètes pour les bâtiments en charpente métallique, comprenant la conception, la fabrication et la fourniture, en utilisant des logiciels d’ingénierie internationalement reconnus ainsi que des éq…',
  about_text = 'Acero Building Systems (Acero) propose des solutions complètes pour les bâtiments en charpente métallique, comprenant la conception, la fabrication et la fourniture, en utilisant des logiciels d’ingénierie internationalement reconnus ainsi que des équipements de production de pointe ou avancés. Le siège social et l’usine de fabrication d’Acero sont situés à Jebel Ali, Dubaï, aux Émirats Arabes Unis. Acero suit un Système de Management Intégré (IMS) comprenant un Système de Management de la Qualité, un Système de Management Environnemental, un Système de Management de la Santé et de la Sécurité au Travail, ainsi qu’un Système de Management de la Fusion du Soudage, certifiés respectivement selon les normes ISO 9001, ISO 14001, ISO 45001 et ISO 3834 et AS/NZS ISO 3834 (Australia et Nouvelle-Zélande), respectivement. Acero est également certifié conformément aux normes européennes EN-1090 (Europe), et le sigle CE est apposé sur ses produits (Certification CE). Acero est spécialisé dans les bâtiments pré-conçus en charpente métallique (solutions rapides et personnalisées), les bâtiments conventionnels en charpente métallique, les systèmes de toiture et de mur, les systèmes de rayonnages, les cabines modulaires et les accessoires du bâtiment. Avec un personnel hautement expérimenté dans l’industrie de la construction métallique et l’une des plus grandes usines de fabrication, Acero sert le marché mondial de la construction métallique.',
  phone = '+212666325149',
  email = 'contact@acero-building-systems.placeholder.ma',
  website_url = 'http://acero.ae',
  ice = '003653353000030',
  avatar_url = 'https://lechantier.ma/uploads/media/bac8f04c3096.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/bac8f04c3096.webp',
