UPDATE public.profiles SET
  username = 'lc-bounouilomar',
  full_name = 'Bounouil OMAR',
  profession = 'Metal frame',
  location = 'Larache',
  bio = 'عمر اللحام انا شخصية متميزة في مجال اللحام، حيث يمتلك خبرة واسعة تمتد ل15 عامًا، وقد عمل في مختلف المواقع والصناعات، مما جعله يجمع بين الخبرة العملية والتنوع في التعامل مع التحديات المختلفة. \*الخبرة العملية:\* - \*اللحام بالقوس الكهربائي (SMAW):\* ل…',
  about_text = 'عمر اللحام انا شخصية متميزة في مجال اللحام، حيث يمتلك خبرة واسعة تمتد ل15 عامًا، وقد عمل في مختلف المواقع والصناعات، مما جعله يجمع بين الخبرة العملية والتنوع في التعامل مع التحديات المختلفة. \*الخبرة العملية:\* - \*اللحام بالقوس الكهربائي (SMAW):\* لديه خبرة واسعة في استخدام هذه الطريقة التقليدية، حيث يمكنه التعامل مع مختلف أنواع المعادن والسماكات. - \*اللحام بالغاز (GTAW أو TIG):\* يجيد استخدام هذه الطريقة التي تتطلب دقة عالية، خاصة في التعامل مع المعادن الرقيقة أو السبائك الخاصة. - \*اللحام بالدفق (FCAW):\* يمكنه التعامل مع هذه الطريقة التي تجمع بين مزايا اللحام بالقوس الكهربائي واللحام بالغاز، مما يزيد من كفاءة العمل. \*العمل في مختلف المواقع:\* - \*الصناعات الثقيلة:\* عمل في مصانع الصلب والهياكل المعدنية، حيث تعامل مع مشاريع كبيرة وضخمة تتطلب دقة وجودة عالية. - \*البناء والتشييد:\* شارك في مشاريع البناء الكبيرة، حيث كان مسؤولاً عن لحام الهياكل المعدنية والجسور. - \*الصناعات النفطية والغازية:\* عمل في مشاريع تتعلق بالأنابيب والخزانات، حيث كانت الدقة والجودة أمورًا بالغة الأهمية لضمان السلامة والكفاءة. \*المهارات الشخصية:\* - \*التواصل الفعال:\* يمكنه التواصل بشكل فعال مع أعضاء الفريق والمديرين، مما يساعده في تقديم التقارير الدقيقة وتنفيذ التوجيهات بدقة. - \*حل المشكلات:\* يمتلك القدرة على تحليل المشكلات التي تواجهه أثناء العمل وإيجاد حلول فعالة لها بسرعة. - \*الالتزام بالسلامة:\* يولي أهمية كبيرة لاتباع إجراءات السلامة، مما يضمن سلامته وسلامة زملائه في بيئة العمل. بفضل هذه الخبرات والمهارات، يعتبر عمر اللحام شخصية موثوقة وذات قيمة عالية في مختلف الصناعات التي تتطلب خبرة في اللحام.',
  phone = '+212645187598',
  email = 'lc-bounouilomar@lechantier.sifarah.local',
  website_url = NULL,
  ice = NULL,
  avatar_url = 'https://lechantier.ma/uploads/media/932b07199c41.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/932b07199c41.webp',
  profile_type = 'enterprise',
  internal_category_id = (SELECT id FROM public.internal_categories WHERE code = '3.3.5' LIMIT 1),
  updated_at = NOW()
WHERE id = '32d614f3-b70d-569d-837d-1279d2f681fe'::uuid;
