UPDATE public.profiles SET
  username = 'lc-vetco',
  full_name = 'VETCO',
  profession = 'Construction materials',
  location = 'Agadir',
  bio = 'La société VETCO (Vente et Transformation de matériaux de Construction) est une entreprise marocaine basée à Biougra, dans la région d’Agadir, spécialisée dans la fabrication et la commercialisation de matériaux de construction. Grâce à une expertise…',
  about_text = 'La société VETCO (Vente et Transformation de matériaux de Construction) est une entreprise marocaine basée à Biougra, dans la région d’Agadir, spécialisée dans la fabrication et la commercialisation de matériaux de construction. Grâce à une expertise solide et un engagement permanent envers la qualité, VETCO s’impose comme un partenaire de confiance pour les professionnels et les particuliers du secteur du bâtiment. Notre entreprise propose une gamme variée de produits, notamment : Des blocs en béton (agglos 10, 15, 20, 7), Des hourdis (16P, 15N, 12P), Du ciment, Des pointes (clous), Du fil de fer, Des PTS (poutrelles treillis soudées), Des poutrelles métalliques, Et du fer à béton. Équipée de machines performantes et d’une équipe expérimentée, VETCO garantit des produits conformes aux normes marocaines en vigueur, tout en assurant des délais de livraison rapides et un service client réactif. Notre vision est centrée sur la qualité, la fiabilité, et la proximité avec nos clients. En intégrant continuellement les meilleures pratiques du secteur, VETCO contribue activement au développement de projets de construction durables dans la région du Souss-Massa.',
  phone = '+212528810080',
  email = 'vetco@menara.ma',
  website_url = 'https://vetco-sarl.com',
  ice = '001643061000012',
  avatar_url = 'https://lechantier.ma/uploads/media/9489957e0801.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/9489957e0801.webp',
  profile_type = 'enterprise',
