UPDATE public.profiles SET
  username = 'lc-becomar',
  full_name = 'BECOMAR',
  profession = 'Construction materials',
  location = 'Berrechid',
  bio = 'BECOMAR est une entreprise marocaine spécialisée dans la production et la commercialisation de solutions béton innovantes et de qualité supérieure. Fondée pour répondre aux besoins croissants du marché de la construction, elle s''appuie sur une expert…',
  about_text = 'BECOMAR est une entreprise marocaine spécialisée dans la production et la commercialisation de solutions béton innovantes et de qualité supérieure. Fondée pour répondre aux besoins croissants du marché de la construction, elle s''appuie sur une expertise technique pointue et des moyens de production modernes pour offrir à ses clients des produits fiables et durables. L’offre de BECOMAR couvre une large gamme de produits en béton préfabriqué, allant des agglos, poutrelles et hourdis certifiés aux normes marocaines, aux solutions de post-tension, en passant par les éléments précontraints et les produits spéciaux conçus sur mesure pour les projets les plus exigeants. BECOMAR met un point d’honneur à innover en permanence, investissant dans la recherche et le développement pour anticiper les tendances du marché et proposer des solutions performantes. Son laboratoire interne assure un contrôle qualité rigoureux à chaque étape du processus de production, garantissant la conformité et la fiabilité de ses produits. Soutenu par un service client réactif et une équipe d’ingénieurs et de techniciens qualifiés, BECOMAR accompagne ses clients dans la réalisation de leurs projets, de la conception à la livraison. Grâce à son engagement pour la qualité et sa vision tournée vers l’avenir, BECOMAR s’impose comme un partenaire de confiance et un acteur majeur du secteur du béton au Maroc.',
  phone = '+212522324024',
  email = 'contact@becomar.net',
  website_url = 'https://www.becomar.org',
  ice = '001533135000008',
  avatar_url = 'https://lechantier.ma/uploads/media/60eb3b2f7b3b.webp',
  cover_photo_url = 'https://lechantier.ma/uploads/media/60eb3b2f7b3b.webp',
  profile_type = 'enterprise',
