UPDATE public.profiles SET
  username = 'lc-8375',
  full_name = 'IADIS',
  profession = 'Étanchéité',
  location = 'Casablanca',
  bio = 'IADIS est une entreprise marocaine spécialisée dans la distribution de fournitures, équipements et solutions industrielles destinées aux professionnels de l’industrie, du bâtiment, de la maintenance et des services techniques. Nous accompagnons nos c…',
  about_text = 'IADIS est une entreprise marocaine spécialisée dans la distribution de fournitures, équipements et solutions industrielles destinées aux professionnels de l’industrie, du bâtiment, de la maintenance et des services techniques. Nous accompagnons nos clients dans l’ensemble de leurs besoins : identification des références, sourcing, chiffrage, fourniture, livraison et suivi commercial. Notre catalogue couvre notamment les équipements de protection individuelle (EPI), l’outillage à main et électroportatif, les roulements et éléments de transmission, les abrasifs, les produits chimiques, les adhésifs techniques ainsi que les consommables industriels. Selon les besoins et la disponibilité, nous proposons et sourçons des produits de marques reconnues telles que **SKF, LOCTITE, NORTON, WÜRTH, FLUKE et FORANE**, ainsi que d’autres références adaptées aux exigences techniques de nos clients. IADIS s’adresse principalement aux services achats, maintenance, production, HSE/QHSE, responsables techniques et entreprises ayant besoin de solutions fiables et compétitives. Notre objectif est d’offrir un service réactif, une bonne disponibilité des produits, des prix compétitifs et un accompagnement personnalisé. Grâce à notre réseau de fournisseurs et partenaires, nous sommes également en mesure de rechercher des références spécifiques ou difficiles à trouver afin de répondre efficacement aux demandes urgentes ou particulières de nos clients',
  phone = '+212663568982',
  email = 'contact@iadis.placeholder.ma',
  website_url = 'https://iadis.ma',
  ice = '002068351000042',
  avatar_url = 'https://tachrone-profile-logos-pro.s3.eu-west-3.amazonaws.com/file-163d2f8e-1a63-4936-832c-4db2a4ed99b1.png',
