INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('6e4f51ba-6877-5700-8f43-720b90defc8f'::uuid, '66e2e6cb-2a11-5910-9739-a5599a10430d'::uuid, 'Maîtrise d''œuvre architecturale — conception et suivi', 'Mission de professionnels BTP portée par Accord Architecture, basé à Agadir. Chez Accord Architecture, notre vision est de transformer vos idées en un exemple d’excellence architecturale, en créant des espaces qui allient beauté, fonctionnalité et durabilité. La mission couvre typiquement les volets étude / accompagnement : Structure légère en coquille, Construction d un immeuble en r+5, Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu. Accord Architecture intervient à Agadir, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation architect, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Architecture / Ingénierie', 'https://lechantier.ma/uploads/media/100fbe409f4e.webp', '["https://lechantier.ma/uploads/media/100fbe409f4e.webp", "https://lechantier.ma/uploads/media/8e3e77ecf2d5.webp"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Structure légère en coquille", "Construction d un immeuble en r+5", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Architect", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Agadir"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, N