INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('2e02d6b8-b90e-5151-8064-94dd1c08329b'::uuid, '1b0df585-4b21-544c-b139-442865619d88'::uuid, 'Painting — offre clé en main', 'Mission de professionnels BTP portée par Renewal, basé à Témara. Nous sommes spécialisés dans tous les travaux d’aménagement et de finition pour les particuliers et les professionnels, incluant la pose de revêtements, les travaux de bois, la peinture, les moulures ainsi que les réalisations en fer et inox. La mission couvre typiquement les volets réalisation / accompagnement : Metal Exteriors, Pose Portes, Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu. Renewal intervient à Témara, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation painting, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Construction Gros Oeuvre', 'https://lechantier.ma/uploads/media/650784cfe2f2.webp', '["https://lechantier.ma/uploads/media/650784cfe2f2.webp", "https://lechantier.ma/uploads/media/dea578c36d56.webp", "https://lechantier.ma/uploads/media/50d04e42cd66.webp", "https://lechantier.ma/uploads/media/9eabafefcdc4.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Metal Exteriors", "Pose Portes", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Painting", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Témara"]'::jsonb,