is', NULL, NULL, 'villes', '["Khouribga"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '8.5.4' LIMIT 1));
