INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('005bce47-7bcf-57f3-9e9e-6f3cd56ea42e'::uuid, '966866e1-f047-5c11-9d20-1564321c1e7c'::uuid, 'Aménagement d''une salle de Billard', 'Conception d’un centre de billard moderne offrant une ambiance élégante et immersive. Le projet comprend un aménagement intérieur contemporain avec un éclairage architectural, des matériaux haut de gamme et une organisation fluide des espaces de jeu. L’objectif est de créer une atmosphère confortable et dynamique, adaptée aux amateurs de billard et', '["https://lechantier.ma/uploads/media/0c3a44bee7ac.webp", "https://lechantier.ma/uploads/media/ec460d99fef0.webp", "https://lechantier.ma/uploads/media/203b02a43efc.webp", "https://lechantier.ma/uploads/media/f520450fb126.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0c3a44bee7ac.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
