INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('97da5846-a545-5648-b8e2-f5253e504f67'::uuid, 'c6b0828d-c932-5316-876a-4c487901fc32'::uuid, 'Restaurant casaemma', 'Le restaurant-lounge La Casa Emma à Rabat est une réalisation d''Archiste. Le projet marie le bohème-chic et le style méditerranéen autour d''une palette de couleurs dominée par le blanc épuré. L''ambiance est créée par des matériaux naturels : plafonds en paille tressée ou voilages drapés, mobilier en rotin/fibres naturelles, et végétation abondant', '["https://lechantier.ma/uploads/media/5ddfaa67b55f.webp", "https://lechantier.ma/uploads/media/5beb93ba18a4.webp", "https://lechantier.ma/uploads/media/570a966aaaa0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5ddfaa67b55f.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('868a1673-1cd2-58c3-b16a-227b186b520f'::uuid, 'c6b0828d-c932-5316-876a-4c487901fc32'::uuid, 'suite parentale de luxe MB', 'Ce projet d''Archiste est une suite parentale de luxe au design moderne et sophistiqué. La réalisation se distingue par l''usage de matériaux haut de gamme (bois sombre, marbre, travertin) dans une palette de couleurs neutres et riches. L''espace intègre un dressing vitré, un coin salon avec cheminée, et un éclairage LED discret, définissant une amb', '["https://lechantier.ma/uploads/media/9650285c22b4.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9650285c22b4.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('8aaad687-6d45-5106-9395-d4a40a06f48c'::uuid, 'c6b0828d-c932-5316-876a-4c487901fc32'::uuid, 'Réalisation — ARCHISTE', NULL, '["https://lechantier.ma/uploads/media/5beb93ba18a4.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5beb93ba18a4.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e83aaf99-3eeb-55d5-a25e-9e773479e4d7'::uuid, 'c6b0828d-c932-5316-876a-4c487901fc32'::uuid, 'Réalisation — ARCHISTE', NULL, '["https://lechantier.ma/uploads/media/570a966aaaa0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/570a966aaaa0.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d9fbc55c-0ff8-5cf0-b77d-ae10d054f32d'::uuid, '6fc5e188-20ac-54ff-ab94-2c23e62c088a'::uuid, 'BMCI - Data Center', 'Rénovation et aménagement du local technique et du Data Center de la BMCI. Conception d’un espace sécurisé, fonctionnel et moderne intégrant des armoires de précision, systèmes de contrôle, sécurité incendie et mobilier sur mesure pour la zone d’accueil technique.', '["https://lechantier.ma/uploads/media/cb2f98306318.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cb2f98306318.webp', 'Settat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5ff5e13a-2533-5620-a97f-02931003ee88'::uuid, '6fc5e188-20ac-54ff-ab94-2c23e62c088a'::uuid, 'SALON MAROCAIN MODERNE', 'Ce salon marocain moderne allie authenticité et élégance contemporaine. Les lignes épurées se marient aux motifs traditionnels, créant un équilibre harmonieux entre culture et modernité. Les tons neutres, les matériaux nobles et l’éclairage doux apportent chaleur et raffinement à l’espace.', '[]'::jsonb, NULL, 'Settat', (SELECT id FROM public.internal_categories WHERE code = '5.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2f64f879-fa30-597f-8b3b-f8da0edbc075'::uuid, 'e239b585-c356-5f83-8b34-c8680b6c995d'::uuid, 'Réalisation — TAQATECH ENGINEERING', '29 RUE MOHAMED EL BAAMRANI RES SARA 2 ETG 2 N° 206', '["https://lechantier.ma/uploads/media/c31422b88485.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c31422b88485.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
