INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('8256316d-1a82-5a1f-a27f-46de9869df23'::uuid, 'baa95e45-3700-5baa-bfd2-bd9abd269e11'::uuid, 'Réalisation — Solution Toiture', 'Bur 303 IMM 02 BLOC A Oasis Agadir', '["https://lechantier.ma/uploads/media/5ea3a0ccab98.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5ea3a0ccab98.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.2.7' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('59575c9f-981d-5250-bcce-b1c42dff729c'::uuid, 'dbb0d14a-aea1-534d-b1db-f7a33bb7f874'::uuid, 'الزليج البلدي', 'الزليج البلدي هو فن فسيفساء مغربي تقليدي. ​عبارة عن قطع صغيرة من الفخار الملون والمزجج، تُقطع يدوياً وتُجمع لتُشكل أنماطاً هندسية معقدة وجميلة لتزيين الجدران والأرضيات. يتميز بلمعانه وألوانه الزاهية', '["https://lechantier.ma/uploads/media/d086c62d7bf1.webp", "https://lechantier.ma/uploads/media/4de8b8ebd581.webp", "https://lechantier.ma/uploads/media/70c1f565b60b.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d086c62d7bf1.webp', 'Salé', (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
