INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('73db1272-41e5-5436-84ca-d31934561153'::uuid, '42e39c2f-b5ab-5191-9c61-dd004e377a67'::uuid, 'Projet jnan al alia', '​Réalisation des travaux de peinture complète pour ce projet (finitions intérieures). Le travail a compris la préparation complète des surfaces (rebouchage, application d''enduit et ponçage) pour garantir un support lisse, suivie de l''application de peinture de haute qualité. Finitions soignées, respect des détails et propreté absolue du chantier après intervention.', '["https://lechantier.ma/uploads/media/302adfbfe03f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/302adfbfe03f.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.2' LIMIT 1));
