INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('788f2e11-f677-58e9-af5a-ebdd795b6576'::uuid, '025c3803-1b9c-58b7-ac60-5a8991ca5400'::uuid, 'FACULTE DE MEDECINE&PHARMACIE DE RABAT', 'Les travaux d’aménagement de la réserve des produits chimiques de la FMPR ont coûté plus de 1.5 MDH. Ils ont porté sur plusieurs corps d’état, notamment : les travaux de démolition et de construction, Plomberie, climatisation et d’électricité, les revêtements de sol et muraux, la pose de faux plafonds modulaire, la menuiserie aluminium, etc', '["https://lechantier.ma/uploads/media/b2c8e22fd64f.webp", "https://lechantier.ma/uploads/media/246fb7172e09.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b2c8e22fd64f.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
