INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e396abf9-d093-5c38-995f-6319aaee44a7'::uuid, 'ddc0fc3d-6934-5625-b4a3-573fa74acd58'::uuid, 'Spécialistes des solutions sur mesure pour vos projets', 'CONSTRUIRE, RÉNOVER, AMÉNAGER L''excellence technique au service de vos projets Depuis 10 ans, AMG allie savoir-faire technique et vision architecturale pour des réalisations durables. Notre approche sur mesure intègre chaque détail structurel et esthétique, de la conception aux finitions premium.', '["https://amg.co.ma/wp-content/uploads/2025/04/Projet-2.webp"]'::jsonb, 'https://amg.co.ma/wp-content/uploads/2025/04/Projet-2.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
