INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('27a831c2-384d-587b-ad08-0f4bd566d964'::uuid, 'ddc0fc3d-6934-5625-b4a3-573fa74acd58'::uuid, 'L''excellence technique au service de vos projets', 'Depuis 10 ans, AMG allie savoir-faire technique et vision architecturale pour des réalisations durables. Notre approche sur mesure intègre chaque détail structurel et esthétique, de la conception aux finitions premium.', '["https://amg.co.ma/wp-content/uploads/2025/04/Projet-10.webp"]'::jsonb, 'https://amg.co.ma/wp-content/uploads/2025/04/Projet-10.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f57f5fc3-cdcb-5a4e-bab9-dd599fd2c7d3'::uuid, 'ddc0fc3d-6934-5625-b4a3-573fa74acd58'::uuid, '10 ANS D''EXPERTISE AU SERVICE DE VOS PROJETS', 'Depuis 10 ans, nous concrétisons vos visions en espaces pérennes, combinant études précises, exécution irréprochable et finitions d excellence.', '["https://amg.co.ma/wp-content/uploads/2025/04/Projet-11.webp"]'::jsonb, 'https://amg.co.ma/wp-content/uploads/2025/04/Projet-11.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('022e2d2a-06a6-5cc4-ae14-e1023d6eab0d'::uuid, 'a53e5ab9-b9c4-5c2c-8894-59dc966d5a86'::uuid, 'Toutes nos réalisations →', 'Zones d''intervention Basés à Marrakech, nous intervenons partout au Maroc. Fabrication et pose de menuiserie aluminium pour les particuliers, promoteurs et professionnels à Marrakech, dans sa région et dans les principales villes du Royaume. Marrakech Guéliz Targa Amelkis La Palmeraie Tamansourt Aït Ourir Chichaoua Casablanca Rabat Agadir Essaouira Béni Mellal Zagora </d', '["https://apex-alu.com/images/hero.jpg"]'::jsonb, 'https://apex-alu.com/images/hero.jpg', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('50c40c47-9361-56f3-b50b-a83fa39431c0'::uuid, 'a53e5ab9-b9c4-5c2c-8894-59dc966d5a86'::uuid, 'Votre projet, notre prochain chantier →', '© 2026 APEX ALU — Menuiserie Aluminium, Marrakech. Accueil · Services · Devis · Contact · AR Mentions légales · Politique de confidentialité <path d="M16 .8C7.6.8.8 7.6.8 16c0 2.7.7 5.3 2 7.6L.8 31.2l7.8-2c2.2 1.2 4.7 1.9 7.4 1.9 8.4 0 15.2-6.8 15.2-15.2S24.4.8', '["https://apex-alu.com/images/service-fenetres.jpg"]'::jsonb, 'https://apex-alu.com/images/service-fenetres.jpg', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a39d38bc-10ff-5942-a63c-cbd45665c7ad'::uuid, 'a53e5ab9-b9c4-5c2c-8894-59dc966d5a86'::uuid, 'Voir nos réalisations', 'Sur mesure fabrication en atelier Pose incluse par notre propre équipe Devis 48 h gratuit et sans engagement Profilés RAL 7016 · Anthracite Nos services Tout ce qui se fait en aluminium, nous le fabriquons. <', '["https://apex-alu.com/images/service-portes.jpg"]'::jsonb, 'https://apex-alu.com/images/service-portes.jpg', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e7a08eaa-3aec-5bc5-8643-855ecd72094f'::uuid, 'a53e5ab9-b9c4-5c2c-8894-59dc966d5a86'::uuid, 'Karim B. Villa — La Palmeraie', '« Devis rapide et clair, profilés de qualité et un vrai conseil sur le vitrage. Le résultat est à la hauteur, l''isolation a beaucoup changé. »', '["https://apex-alu.com/images/service-verandas.jpg"]'::jsonb, 'https://apex-alu.com/images/service-verandas.jpg', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('864b6016-4733-5ca3-bca1-601ce0764b44'::uuid, '73e482fe-6635-574e-82f1-660db5f0f4eb'::uuid, 'Transformez vos projets en réalité', 'Qu’il s’agisse de construire une villa moderne, de rénover un immeuble, d’aménager un espace vert ou d’installer des systèmes techniques (plomberie, électricité, climatisation), notre équipe se tient prête à relever vos défis.', '["https://arahalglobalservices.com/wp-content/uploads/2025/10/arahal-vest.jpg"]'::jsonb, 'https://arahalglobalservices.com/wp-content/uploads/2025/10/arahal-vest.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
