INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('dcae8922-9c61-54ac-bae2-a2144284b2aa'::uuid, 'be846853-97b9-55e0-8719-a59912abac57'::uuid, 'Structures métalliques préfabriquées : gagner du temps et de la qualité pour vos projets industriels au Maroc', 'Saviez-vous qu une charpente métallique préfabriquée peut réduire les délais de construction jusqu à 40%? Face à des calendriers de plus en plus serrés, les industriels et maîtres d oeuvre au Maroc cherchent…', '["https://i0.wp.com/www.anapro.ma/wp-content/uploads/2026/06/structures-metalliques-prefabriquees-gagner-du-temps-et-de-la-qualite-pour-vos-projets-industriels-au-maroc.jpg?fit=1080%2C720&ssl=1"]'::jsonb, 'https://i0.wp.com/www.anapro.ma/wp-content/uploads/2026/06/structures-metalliques-prefabriquees-gagner-du-temps-et-de-la-qualite-pour-vos-projets-industriels-au-maroc.jpg?fit=1080%2C720&ssl=1', 'Mohammedia', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
