INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4868c3ff-e8fc-5235-8f44-a74ab2f43e96'::uuid, 'be846853-97b9-55e0-8719-a59912abac57'::uuid, 'Quels types de projets prenez-vous en charge ?', 'Nous intervenons sur des projets standards comme sur des demandes spécifiques, quel que soit le secteur d’activité.', '["https://i0.wp.com/www.anapro.ma/wp-content/uploads/2026/06/structures-metalliques-prefabriquees-gagner-du-temps-et-de-la-qualite-pour-vos-projets-industriels-au-maroc.jpg?resize=300%2C200&ssl=1"]'::jsonb, 'https://i0.wp.com/www.anapro.ma/wp-content/uploads/2026/06/structures-metalliques-prefabriquees-gagner-du-temps-et-de-la-qualite-pour-vos-projets-industriels-au-maroc.jpg?resize=300%2C200&ssl=1', 'Mohammedia', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
