INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('8b51afc3-796a-5ee1-aac6-007fe04beaed'::uuid, '1cac841f-0026-5e83-ae68-430def47f695'::uuid, 'Notre savoir-faire au service de vos projets', 'Nos domaines d’intervention Construction de bâtiments Nous réalisons des structures durables et fonctionnelles : logements collectifs, bureaux, écoles, hôpitaux, centres culturels et infrastructures industrielles.', '["https://www.engor.net/wp-content/uploads/2026/05/construction.png"]'::jsonb, 'https://www.engor.net/wp-content/uploads/2026/05/construction.png', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('caedeef0-1769-5089-b031-798eef494cdd'::uuid, '1cac841f-0026-5e83-ae68-430def47f695'::uuid, 'Gestion de projet globale', 'De la conception à la livraison, nous prenons en charge l’ensemble du projet : études, coordination des corps d’état, réalisation et mise en service.', '["https://www.engor.net/wp-content/uploads/2026/05/house.png"]'::jsonb, 'https://www.engor.net/wp-content/uploads/2026/05/house.png', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
