INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('fe051868-e70d-54f2-8e68-d8ef0fb8d673'::uuid, 'd88029e6-14b0-588a-8dda-0216eaf48f1f'::uuid, 'Quels sont vos délais moyens pour la réalisation des projets ?', 'Les délais de réalisation dépendent de la taille et de la complexité du projet. Lors de l élaboration du devis, nous vous fournirons un calendrier détaillé des étapes de votre projet.', '["https://gecova.ma/wp-content/uploads/2024/06/builderon-img5-100x100.png"]'::jsonb, 'https://gecova.ma/wp-content/uploads/2024/06/builderon-img5-100x100.png', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
